        """[E_pp, E_pm} = 0  ((a_1^+)^2 = 0)"""
        comps = _get(self.sc, 'E_eps1_del1_pp', 'E_eps1_del1_pm')
        assert not comps

    def test_E_mp_E_mm_zero(self):
        """[E_mp, E_mm} = 0  ((a_1^-)^2 = 0, no -2ε root)"""
        comps = _get(self.sc, 'E_eps1_del1_mp', 'E_eps1_del1_mm')
        assert not comps

