        """[H_2, E_2del1_p} = -2·E_2del1_p  (root 2δ_1 acts on H_2 = -n_1 - 1/2)"""
        comps = _get(self.sc, 'H_2', 'E_2del1_p')
        assert comps == {'E_2del1_p': Fraction(-2)}

